def find_regions(grid, color):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and not visited[r][c]:
                comp = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                            if grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                min_r, max_r = min(row for row,col in comp), max(row for row,col in comp)
                min_c, max_c = min(col for row,col in comp), max(col for row,col in comp)

                interior_raw = [(r,c) for r in range(min_r, max_r+1) 
                               for c in range(min_c, max_c+1)
                               if not ((r,c) in comp)]

                regions.append({
                    'color': color,
                    'cells': comp,
                    'min_r': min_r, 'max_r': max_r,
                    'min_c': min_c, 'max_c': max_c, 
                    'interior_cells': interior_raw,  # Note: interior_cells is KEY
                })
    return regions

